import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);

  const state = {
    columnY: 0,
    velocity: 0,
    inertiaTimeline: null,
    animationFrameId: null,
  };

  const colors = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  const PLATE_WIDTH = 1.9;
  const PLATE_HEIGHT = 1.2;
  const PLATE_PITCH = 1.5;
  const COLUMN_X = 0.9;
  const NUM_PLATES = 6;
  const BEVEL_SIZE = 0.03;

  const baseTexture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');

  // Create plates
  const plates = [];
  const accentMaterials = [];

  for (let i = 0; i < NUM_PLATES; i++) {
    const plateGroup = new THREE.Group();
    plateGroup.userData.plateIndex = i;
    plateGroup.userData.baseY = i * PLATE_PITCH;

    // Image plate
    const plateGeom = new THREE.PlaneGeometry(PLATE_WIDTH, PLATE_HEIGHT);
    const plateMat = new THREE.MeshStandardMaterial({
      map: baseTexture,
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
    });
    const plateMesh = new THREE.Mesh(plateGeom, plateMat);
    plateGroup.add(plateMesh);

    // Bevel frames
    const bevelMatInk = new THREE.MeshStandardMaterial({
      color: colors.ink,
      roughness: 0.5,
      metalness: 0.5,
    });

    const leftBevelGeom = new THREE.PlaneGeometry(BEVEL_SIZE, PLATE_HEIGHT + 2 * BEVEL_SIZE);
    const leftBevel = new THREE.Mesh(leftBevelGeom, bevelMatInk.clone());
    leftBevel.position.set(-(PLATE_WIDTH / 2 + BEVEL_SIZE / 2), 0, 0.001);
    plateGroup.add(leftBevel);

    const rightBevel = new THREE.Mesh(leftBevelGeom, bevelMatInk.clone());
    rightBevel.position.set(PLATE_WIDTH / 2 + BEVEL_SIZE / 2, 0, 0.001);
    plateGroup.add(rightBevel);

    const topBevelGeom = new THREE.PlaneGeometry(PLATE_WIDTH + 2 * BEVEL_SIZE, BEVEL_SIZE);
    const topBevel = new THREE.Mesh(topBevelGeom, bevelMatInk.clone());
    topBevel.position.set(0, PLATE_HEIGHT / 2 + BEVEL_SIZE / 2, 0.001);
    plateGroup.add(topBevel);

    const bottomBevel = new THREE.Mesh(topBevelGeom, bevelMatInk.clone());
    bottomBevel.position.set(0, -(PLATE_HEIGHT / 2 + BEVEL_SIZE / 2), 0.001);
    plateGroup.add(bottomBevel);

    // Accent strip (left edge, emissive)
    const accentGeom = new THREE.PlaneGeometry(0.03, PLATE_HEIGHT);
    const accentMat = new THREE.MeshBasicMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: 1.4,
      transparent: true,
      opacity: 0,
    });
    const accentStrip = new THREE.Mesh(accentGeom, accentMat);
    accentStrip.position.set(-(PLATE_WIDTH / 2), 0, 0.002);
    plateGroup.add(accentStrip);
    accentMaterials.push(accentMat);

    plateGroup.position.set(COLUMN_X, plateGroup.userData.baseY, 0);
    group.add(plateGroup);
    plates.push(plateGroup);
  }

  // Create captions
  const captions = [
    "DIAL ROOM",
    "ESCAPEMENT BENCH",
    "CNC HALL",
    "FINISHING LAB",
    "ARCHIVE VAULT",
    "ASSEMBLY LINE ONE",
  ];

  const captionMeshes = [];

  captions.forEach((captionText, i) => {
    const mesh = ctx.fontAtlas.createText(captionText, {
      fontSize: 18,
      fontWeight: 400,
      family: "JetBrains Mono",
      color: colors.paper,
    });
    mesh.userData.baseY = i * PLATE_PITCH;
    mesh.position.set(-1.6, mesh.userData.baseY, 0);

    if (mesh.material) {
      if (Array.isArray(mesh.material)) {
        mesh.material.forEach(m => {
          m.transparent = true;
          m.opacity = 0;
        });
      } else {
        mesh.material.transparent = true;
        mesh.material.opacity = 0;
      }
    }

    group.add(mesh);
    captionMeshes.push(mesh);
  });

  // Header (pinned)
  const headerMesh = ctx.fontAtlas.createText("Inside the atelier", {
    fontSize: 68,
    fontWeight: 600,
    family: "Lora",
    color: colors.paper,
  });
  headerMesh.position.set(-1.6, 1.9, 0);
  group.add(headerMesh);

  // Animation loop
  const updateGallery = () => {
    if (Math.abs(state.velocity) > 0.0001) {
      state.velocity *= (1 - 0.12);
      state.columnY += state.velocity;
    }

    plates.forEach((plate, idx) => {
      const currentY = plate.userData.baseY + state.columnY;
      plate.position.y = currentY;

      const distToFocus = Math.abs(currentY);
      let targetScale = 1.0;
      if (distToFocus < 0.6) {
        targetScale = 1.0 + (1 - distToFocus / 0.6) * 0.06;
      }

      gsap.to(plate.scale, {
        x: targetScale,
        y: targetScale,
        duration: 0.35,
        ease: "cubic-bezier(0.215,0.61,0.355,1)",
        overwrite: 'auto',
      });

      let accentOpacity = 0;
      if (distToFocus < 0.4) {
        accentOpacity = Math.max(0, 1 - distToFocus / 0.4);
      }
      accentMaterials[idx].opacity = accentOpacity;
    });

    captionMeshes.forEach((caption) => {
      const currentY = caption.userData.baseY + state.columnY;
      caption.position.y = currentY;

      const distToFocus = Math.abs(currentY);
      let opacity = 0;
      if (distToFocus < 1.0) {
        opacity = Math.max(0, 1 - distToFocus / 1.0);
      }

      if (caption.material) {
        if (Array.isArray(caption.material)) {
          caption.material.forEach(m => {
            m.opacity = opacity;
          });
        } else {
          caption.material.opacity = opacity;
        }
      }
    });
  };

  const animate = () => {
    updateGallery();
    state.animationFrameId = requestAnimationFrame(animate);
  };
  animate();

  // Scroll handler
  const onScroll = (event) => {
    if (state.inertiaTimeline) {
      state.inertiaTimeline.kill();
    }

    const delta = event.deltaY || 0;
    const viewportHeight = window.innerHeight || 1080;
    state.velocity = (delta / viewportHeight) * 1.5;

    state.inertiaTimeline = gsap.delayedCall(0.05, () => {
      gsap.to(state, {
        velocity: 0,
        duration: 0.9,
        ease: "cubic-bezier(0.165,0.84,0.44,1)",
      });
    });
  };

  // Apply cinematic primitive
  if (ctx.primitives && typeof ctx.primitives['fly-through'] === 'function') {
    ctx.primitives['fly-through'](group, { depthUnits: 2.5 });
  }

  // Attach handlers
  group.userData.handlers = {
    onScroll: onScroll,
  };

  // Cleanup
  group.userData.cleanup = () => {
    if (state.animationFrameId) {
      cancelAnimationFrame(state.animationFrameId);
    }
    if (state.inertiaTimeline) {
      state.inertiaTimeline.kill();
    }

    baseTexture.dispose();

    plates.forEach((plate) => {
      plate.traverse((node) => {
        if (node instanceof THREE.Mesh) {
          if (node.geometry) node.geometry.dispose();
          if (node.material) {
            if (Array.isArray(node.material)) {
              node.material.forEach(m => m.dispose());
            } else {
              node.material.dispose();
            }
          }
        }
      });
    });

    captionMeshes.forEach((mesh) => {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) {
        if (Array.isArray(mesh.material)) {
          mesh.material.forEach(m => m.dispose());
        } else {
          mesh.material.dispose();
        }
      }
    });
  };

  return group;
}
